"""X11 text commits using selection transfer, without temporary keyboard maps.

The selection owner survives the paste so the previous clipboard (including
binary/rich formats) remains available. All Xlib access belongs to one thread.
No clipboard contents are logged. Uses the existing python-xlib dependency.
"""
import asyncio
from concurrent.futures import Future
import logging
import os
import queue
import select
import subprocess
import threading
import time

from Xlib import X, Xatom, display, protocol, error

log = logging.getLogger("webrtc_input")
MAX_BYTES = 32 * 1024 * 1024
CHUNK_BYTES = 48 * 1024
_bridges = {}
_bridge_lock = threading.Lock()


class SelectionOwner:
    def __init__(self, display_name):
        self.display_name = display_name
        self.jobs = queue.Queue()
        self.state_lock = threading.Lock()
        self.closed = False
        self.ready = Future()
        threading.Thread(target=self._run, name="x11-text-selection", daemon=True).start()
        self.ready.result(timeout=5)

    def _run(self):
        try:
            self.d = display.Display(self.display_name)
            # Qt uses StructureNotify and other EWMH clients use SubstructureNotify
            # for replies to _NET_WM_PING. Neither mask claims WM ownership.
            self.d.screen().root.change_attributes(event_mask=X.StructureNotifyMask | X.SubstructureNotifyMask)
            self.window = self.d.screen().root.create_window(
                0, 0, 1, 1, 0, X.CopyFromParent, event_mask=X.PropertyChangeMask)
            self.clipboard = self.atom("CLIPBOARD")
            self.targets = self.atom("TARGETS")
            self.incr = self.atom("INCR")
            self.read_property = self.atom("_SELKIES_TEXT_READ")
            self.ping = self.atom("_NET_WM_PING")
            self.protocols = self.atom("WM_PROTOCOLS")
            self.clock_property = self.atom("_SELKIES_PASTE_TIME")
            self.data = {}
            self.selections = {}
            self.retired_windows = []
            self.transfers = {}
            self.pending_receipts = set()
            self.pasting = False
            self.consumed = False
            self.ready.set_result(True)
        except Exception as exc:
            self.ready.set_exception(exc)
            return
        while True:
            try:
                job = self.jobs.get_nowait()
            except queue.Empty:
                job = None
            if job:
                text, result = job
                try:
                    self._commit(text)
                    result.set_result(True)
                except Exception as exc:
                    result.set_exception(exc)
            try:
                self._event(time.monotonic() + .05)
                now = time.monotonic()
                self.transfers = {k: v for k, v in self.transfers.items() if v[5] > now}
                self._collect_retired_windows()
            except error.ConnectionClosedError:
                # An X server recovery invalidates every resource on this connection.
                with _bridge_lock:
                    _bridges.pop(self.display_name, None)
                with self.state_lock:
                    self.closed = True
                    while not self.jobs.empty():
                        self.jobs.get_nowait()[1].set_exception(RuntimeError("X display disconnected"))
                return
            except Exception:
                log.warning("X11 selection service event failed", exc_info=True)

    def atom(self, name):
        return self.d.intern_atom(name)

    def owner(self):
        owner = self.d.get_selection_owner(self.clipboard)
        return getattr(owner, "id", 0)

    def _collect_retired_windows(self):
        # Briefly serve requests already addressed to an old owner. Bound both
        # lifetime and count; an expired request may fail, never read new data.
        now = time.monotonic()
        while self.retired_windows and (
                self.retired_windows[0][1] <= now or len(self.retired_windows) > 32):
            window, _ = self.retired_windows.pop(0)
            self.selections.pop(window.id, None)
            window.destroy()
        self.d.flush()

    def _publish(self, data):
        # Each clipboard generation gets a distinct owner and immutable data.
        # Reusing one owner for text and restored images lets delayed Qt reads
        # observe the other generation and also leaves owner-keyed MIME caches
        # stale. SelectionRequest.owner identifies which generation was asked.
        previous = self.window
        self.window = self.d.screen().root.create_window(
            0, 0, 1, 1, 0, X.CopyFromParent, event_mask=X.PropertyChangeMask)
        self.data = dict(data)
        self.selections[self.window.id] = self.data
        self.window.set_selection_owner(self.clipboard, X.CurrentTime)
        self.d.sync()
        self.retired_windows.append((previous, time.monotonic() + 5))
        self._collect_retired_windows()

    def _event(self, deadline):
        if not self.d.pending_events():
            select.select([self.d.fileno()], [], [], max(0, min(.05, deadline - time.monotonic())))
        if not self.d.pending_events():
            return None
        event = self.d.next_event()
        if event.type == X.SelectionRequest:
            log.debug("Selection request target=%s client=%s expected=%s",
                      self.d.get_atom_name(event.target), event.requestor.id & ~self.d.display.info.resource_id_mask,
                      getattr(self, "paste_client", None))
            prop = event.property or event.target
            success = self._serve(event.requestor, event.target, prop, event.owner.id)
            event.requestor.send_event(protocol.event.SelectionNotify(
                time=event.time, requestor=event.requestor, selection=event.selection,
                target=event.target, property=prop if success else X.NONE), propagate=False)
            self.d.flush()
        elif event.type == X.PropertyNotify and event.state == X.PropertyDelete:
            key = (event.window.id, event.atom)
            if key in self.pending_receipts:
                self.pending_receipts.discard(key)
                if self.pasting:
                    self.consumed = True
                    self.last_paste_activity = time.monotonic()
            transfer = self.transfers.get(key)
            if transfer:
                kind, fmt, value, offset, text_owner, expires = transfer
                step = CHUNK_BYTES // (fmt // 8)
                chunk = value[offset:offset + step]
                event.window.change_property(event.atom, kind, fmt, chunk)
                self.d.flush()
                if len(chunk):
                    self.transfers[key] = (kind, fmt, value, offset + len(chunk), text_owner, expires)
                else:
                    del self.transfers[key]
                    if self.pasting and text_owner == self.window.id:
                        # The terminating INCR property also needs a receipt.
                        self.pending_receipts.add(key)
        return event

    def _serve(self, requestor, target, prop, owner_id=None):
        data = self.data if owner_id is None else self.selections.get(owner_id)
        if data is None:
            return False
        focused_read = (self.pasting and (owner_id is None or owner_id == self.window.id)
                        and requestor.id & ~self.d.display.info.resource_id_mask == self.paste_client)
        if focused_read:
            self.last_paste_activity = time.monotonic()
        if target == self.targets:
            requestor.change_property(prop, Xatom.ATOM, 32, list(data) + [self.targets])
            return True
        value = data.get(target)
        if value is None:
            return False
        kind, fmt, payload = value
        # Clipboard managers may fetch a new selection before the application.
        # Only the focused X client can acknowledge this text commit.
        is_text = focused_read and target in self.text_targets
        size = len(payload) * (fmt // 8)
        if size <= CHUNK_BYTES:
            if is_text:
                # Property creation/SelectionNotify only queues a reply. The
                # application may still be busy: releasing Enter here can send
                # the message before its asynchronous paste has read the text.
                # ICCCM requestors delete the property after retrieving it.
                requestor.change_attributes(event_mask=X.PropertyChangeMask)
                self.pending_receipts.add((requestor.id, prop))
            requestor.change_property(prop, kind, fmt, payload)
        else:
            requestor.change_attributes(event_mask=X.PropertyChangeMask)
            self.transfers[(requestor.id, prop)] = (
                kind, fmt, payload, 0, self.window.id if is_text else None, time.monotonic() + 30)
            requestor.change_property(prop, self.incr, 32, [size])
        return True

    def _read(self, target, deadline):
        # A timed-out owner may reply after the next conversion starts. Give
        # every read its own requestor, including INCR property notifications.
        # python-xlib immediately reuses the latest freed resource ID: allocate
        # first, then retire the previous reader. Keeping one reader alive makes
        # the next ID distinct without accumulating windows between commits.
        reader = self.d.screen().root.create_window(
            0, 0, 1, 1, 0, X.CopyFromParent, event_mask=X.PropertyChangeMask)
        previous_reader = getattr(self, "_snapshot_reader", None)
        self._snapshot_reader = reader
        if previous_reader is not None:
            previous_reader.destroy()
        try:
            reader.convert_selection(self.clipboard, target, self.read_property, X.CurrentTime)
            self.d.flush()
            while time.monotonic() < deadline:
                event = self._event(deadline)
                if (event is not None and event.type == X.SelectionNotify
                        and event.requestor.id == reader.id and event.target == target
                        and event.selection == self.clipboard):
                    if not event.property:
                        raise RuntimeError("clipboard snapshot target refused")
                    if event.property != self.read_property:
                        continue
                    value = reader.get_full_property(self.read_property, X.AnyPropertyType)
                    reader.delete_property(self.read_property)
                    self.d.flush()
                    if value is None:
                        raise RuntimeError("clipboard snapshot property missing")
                    if value.property_type != self.incr:
                        if len(value.value) * (value.format // 8) > MAX_BYTES:
                            raise OverflowError("clipboard snapshot too large")
                        return value.property_type, value.format, value.value
                    break
            else:
                raise TimeoutError("clipboard snapshot timed out")
            result, kind, fmt, size = [], None, None, 0
            while time.monotonic() < deadline:
                event = self._event(deadline)
                if (event is None or event.type != X.PropertyNotify or event.window.id != reader.id
                        or event.atom != self.read_property or event.state != X.PropertyNewValue):
                    continue
                value = reader.get_full_property(self.read_property, X.AnyPropertyType)
                if value is None or value.property_type == self.incr:
                    continue
                reader.delete_property(self.read_property)
                self.d.flush()
                if kind is None:
                    kind, fmt = value.property_type, value.format
                if (kind, fmt) != (value.property_type, value.format):
                    raise RuntimeError("clipboard snapshot format changed")
                if not len(value.value):
                    return kind, fmt, b"".join(result) if fmt == 8 else [v for part in result for v in part]
                result.append(value.value)
                size += len(value.value) * (fmt // 8)
                if size > MAX_BYTES:
                    raise OverflowError("clipboard snapshot too large")
            raise TimeoutError("clipboard snapshot transfer timed out")
        finally:
            # Release payload memory while retaining this one resource ID as
            # the allocation guard for the next conversion.
            reader.delete_property(self.read_property)
            self.d.flush()

    def _snapshot(self):
        original = self.owner()
        if original == self.window.id:
            return dict(self.data)
        if not original:
            return {}
        deadline = time.monotonic() + 5
        _, fmt, targets = self._read(self.targets, deadline)
        if fmt != 32 or len(targets) > 128:
            raise RuntimeError("clipboard snapshot invalid targets")
        result, size, has_data = {}, 0, False
        ignored = {"TARGETS", "TIMESTAMP", "MULTIPLE", "SAVE_TARGETS", "DELETE", "INSERT_SELECTION", "INSERT_PROPERTY", "INCR", "TARGET_SIZES"}
        # Preserve useful formats before optional toolkit-specific aliases can
        # consume the shared budget. A refused alias must not disable all IME
        # commits while perfectly readable text, images or HTML remain present.
        preferred = ("UTF8_STRING", "image/png", "text/html", "text/plain;charset=utf-8",
                     "text/plain;charset=UTF-8", "text/plain", "image/jpeg", "image/webp",
                     "image/bmp", "image/tiff", "application/x-qt-image", "text/uri-list",
                     "x-special/gnome-copied-files", "text/rtf", "application/rtf", "text/richtext")
        ranked = {name: index for index, name in enumerate(preferred)}
        named_targets = [(target, self.d.get_atom_name(target)) for target in dict.fromkeys(targets)]
        has_plain_text = any(name == "UTF8_STRING" or name.startswith("text/plain") for _, name in named_targets)

        def required(name):
            return (name in ranked or name.startswith(("image/", "text/plain;", "text/html;"))
                    or (not has_plain_text and name in {"TEXT", "STRING"}))

        named_targets.sort(key=lambda item: (not required(item[1]), ranked.get(item[1], len(ranked))))
        for target, name in named_targets:
            if name in ignored:
                continue
            has_data = True
            # Server-side drawable handles cannot outlive the previous owner.
            if name in {"PIXMAP", "BITMAP"}:
                continue
            if self.owner() != original:
                raise RuntimeError("clipboard changed or cannot be preserved")
            core_format = required(name)
            if time.monotonic() >= deadline:
                if core_format:
                    raise TimeoutError("clipboard snapshot required formats incomplete")
                break
            try:
                # Busy applications may need more than a second to produce an
                # image or finish INCR. Core formats retain the original shared
                # budget; only optional aliases receive a shorter deadline.
                target_deadline = deadline if core_format else min(deadline, time.monotonic() + 1)
                kind, fmt, payload = self._read(target, target_deadline)
                if fmt not in (8, 16, 32):
                    raise RuntimeError("clipboard snapshot unsupported format")
            except (TimeoutError, RuntimeError) as exc:
                # Never replace a readable image/rich clipboard with just its
                # text fallback. Only optional aliases may be skipped. Keep
                # payloads and externally supplied exception text out of logs.
                if core_format:
                    log.warning("Clipboard snapshot required target failed target=%s reason=%s", name, type(exc).__name__)
                    raise RuntimeError("clipboard changed or cannot be preserved") from None
                log.warning("Clipboard snapshot skipped target=%s reason=%s", name, type(exc).__name__)
                continue
            size += len(payload) * (fmt // 8)
            if size > MAX_BYTES:
                raise RuntimeError("clipboard snapshot too large")
            result[target] = kind, fmt, payload
        if (not result and has_data) or self.owner() != original:
            raise RuntimeError("clipboard changed or cannot be preserved")
        return result

    def _ping_window(self, focused):
        # Focus can be on a child of the top-level client window.
        root = self.d.screen().root
        window = focused
        while window.id != root.id and window.id & ~self.d.display.info.resource_id_mask == self.paste_client:
            if self.ping in (window.get_wm_protocols() or ()):
                return window
            window = window.query_tree().parent
        return None

    def _sync_paste_client(self, window, deadline):
        if window is None:
            return
        # The server timestamp identifies this round trip, independently of
        # other WM pings. Keep serving nested selection reads while waiting.
        self.window.change_property(self.clock_property, Xatom.INTEGER, 8, b"")
        self.d.flush()
        stamp = None
        while time.monotonic() < deadline:
            ev = self._event(deadline)
            if ev is None:
                continue
            if (stamp is None and ev.type == X.PropertyNotify and ev.window.id == self.window.id
                    and ev.atom == self.clock_property and ev.state == X.PropertyNewValue):
                stamp = ev.time
                window.send_event(protocol.event.ClientMessage(
                    window=window, client_type=self.protocols, data=(32, [self.ping, stamp, window.id, 0, 0])))
                self.d.flush()
            elif (stamp is not None and ev.type == X.ClientMessage and ev.client_type == self.protocols
                  and ev.window.id == self.d.screen().root.id and ev.data[0] == 32
                  and tuple(ev.data[1][:3]) == (self.ping, stamp, window.id)):
                return
        raise TimeoutError("paste target did not process X events")

    def _finish_paste(self, client_window, deadline):
        while not self.consumed:
            if time.monotonic() >= deadline:
                raise TimeoutError("application did not consume committed text")
            self._event(deadline)
            if self.owner() != self.window.id:
                raise RuntimeError("clipboard replaced during text commit")
        # A toolkit may read text for inspection and issue a new conversion
        # for insertion. That request goes to the current selection owner.
        self._sync_paste_client(client_window, deadline)
        quiet_since = time.monotonic()
        while time.monotonic() < deadline:
            if self.owner() != self.window.id:
                raise RuntimeError("clipboard replaced during text commit")
            quiet_until = max(quiet_since, self.last_paste_activity) + .15
            pending = self.pending_receipts or any(t[4] == self.window.id for t in self.transfers.values())
            if not pending and time.monotonic() >= quiet_until:
                return
            self._event(deadline if pending else min(deadline, quiet_until))
        raise TimeoutError("application did not finish clipboard reads")

    def _commit(self, text):
        focus = self.d.get_input_focus().focus
        focused_id = getattr(focus, "id", 0)
        if focused_id <= 1:
            raise RuntimeError("no focused application for text commit")
        saved = self._snapshot()
        if getattr(self.d.get_input_focus().focus, "id", 0) != focused_id:
            raise RuntimeError("focus changed before text commit")
        utf8 = self.atom("UTF8_STRING")
        self.paste_client = focused_id & ~self.d.display.info.resource_id_mask
        client_window = self._ping_window(focus)
        self.text_targets = {self.atom(n) for n in ("UTF8_STRING", "text/plain;charset=utf-8", "text/plain", "TEXT")}
        self._publish({target: (utf8 if target == self.atom("TEXT") else target, 8, text.encode("utf-8"))
                       for target in self.text_targets})
        try:
            # Drain clipboard-change callbacks before issuing Ctrl+V. Their
            # reads must never acknowledge a paste that hasn't been sent.
            self._sync_paste_client(client_window, time.monotonic() + 8)
            if self.owner() != self.window.id:
                raise RuntimeError("cannot own clipboard for text commit")
            if getattr(self.d.get_input_focus().focus, "id", 0) != focused_id:
                raise RuntimeError("focus changed before paste shortcut")
            shortcut = os.getenv("SELKIES_IME_PASTE_SHORTCUT", "ctrl+v")
            if shortcut not in {"ctrl+v", "ctrl+shift+v", "shift+Insert"}:
                raise ValueError("unsupported IME paste shortcut")
            self.pasting, self.consumed = True, False
            self.last_paste_activity = 0
            self.pending_receipts.clear()
            subprocess.run(["xdotool", "key", "--clearmodifiers", shortcut],
                           env={**os.environ, "DISPLAY": self.display_name},
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=3, check=True)
            self._finish_paste(client_window, time.monotonic() + 8)
        finally:
            self.pasting = False
            self.pending_receipts.clear()
            # Never overwrite a newer copy made by another application.
            if self.owner() == self.window.id:
                self._publish(saved)
            else:
                self.data = {}

    def submit(self, text):
        future = Future()
        with self.state_lock:
            if self.closed:
                future.set_exception(RuntimeError("X display disconnected"))
            else:
                self.jobs.put((text, future))
        return future


async def paste_text(text):
    name = os.environ.get("DISPLAY", ":1")
    def get_bridge():
        with _bridge_lock:
            if name not in _bridges:
                _bridges[name] = SelectionOwner(name)
            return _bridges[name]
    bridge = await asyncio.to_thread(get_bridge)
    operation = asyncio.wrap_future(bridge.submit(text))
    try:
        return await asyncio.shield(operation)
    except asyncio.CancelledError:
        # Finish the selection transaction before connection key cleanup.
        await asyncio.gather(operation, return_exceptions=True)
        raise
